(async () => {
  const pages = figma.root.children;
  const startHere = pages.find(p => p.name.includes("00"));
  if (!startHere) return "Start Here page not found";

  function extractText(node) {
    let result = [];
    if (node.type === "TEXT") {
      result.push({ name: node.name, text: node.characters });
    }
    if ("children" in node) {
      for (const child of node.children) {
        result = result.concat(extractText(child));
      }
    }
    return result;
  }

  return JSON.stringify(extractText(startHere), null, 2);
})();

