  const page1 = figma.root.children.find(p => p.name.includes("Foundations"));
  const page2 = figma.root.children.find(p => p.name.includes("Components"));
  const page4 = figma.root.children.find(p => p.name.includes("Media"));

  function getSubtree(node) {
    if (!node) return null;
    return {
      id: node.id,
      name: node.name,
      type: node.type,
      children: "children" in node ? node.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : []
    };
  }

  return JSON.stringify({
    Foundations: getSubtree(page1),
    Components: getSubtree(page2),
    Media: getSubtree(page4)
  }, null, 2);
})();

