(async () => {
  const compPage = figma.root.children.find(p => p.name.includes("Components"));
  const mediaPage = figma.root.children.find(p => p.name.includes("Media"));
  const foundPage = figma.root.children.find(p => p.name.includes("Foundations"));

  function getAllNodes(node, depth = 0) {
    if (depth > 3) return { id: node.id, name: node.name, type: node.type };
    let res = { id: node.id, name: node.name, type: node.type };
    if ("children" in node) {
      res.children = node.children.map(c => getAllNodes(c, depth + 1));
    }
    return res;
  }

  return JSON.stringify({
    Foundations: getAllNodes(foundPage),
    Components: getAllNodes(compPage),
    Media: getAllNodes(mediaPage)
  }, null, 2);
})();

