(async () => {
  const page = figma.root.children.find(p => p.name.includes("Foundations"));
  function extractText(node) {
    let result = [];
    if (node.type === "TEXT") {
      result.push({ name: node.name, text: node.characters });
    }
    if ("children" in node) {
      for (const child of node.children) {
        result = result.concat(extractText(child));
      }
    }
    return result;
  }
  return JSON.stringify(extractText(page), null, 2);
})();

(async () => {
  // Let's read details of Button (1:23) and Text Field (1:26) to see their properties, sizing, colors, fonts
  const btn = figma.getNodeById("1:23");
  const txt = figma.getNodeById("1:26");

  function getNodeProps(node) {
    if (!node) return null;
    let fills = [];
    if ("fills" in node) fills = node.fills;
    let strokes = [];
    if ("strokes" in node) strokes = node.strokes;
    let strokeAlign = "";
    if ("strokeAlign" in node) strokeAlign = node.strokeAlign;
    let strokeWeight = 0;
    if ("strokeWeight" in node) strokeWeight = node.strokeWeight;
    let cornerRadius = 0;
    if ("cornerRadius" in node) cornerRadius = node.cornerRadius;

    let textProps = {};
    if (node.type === "TEXT") {
      textProps = {
        characters: node.characters,
        fontSize: node.fontSize,
        fontName: node.fontName,
        textAlignHorizontal: node.textAlignHorizontal,
        textAlignVertical: node.textAlignVertical,
        fills: node.fills
      };
    }

    let children = [];
    if ("children" in node) {
      children = node.children.map(getNodeProps);
    }

    return {
      id: node.id,
      name: node.name,
      type: node.type,
      width: node.width,
      height: node.height,
      fills,
      strokes,
      strokeAlign,
      strokeWeight,
      cornerRadius,
      textProps,
      children
    };
  }

  return JSON.stringify({
    Button: getNodeProps(btn),
    TextField: getNodeProps(txt)
  }, null, 2);
})();

