    const bgPhoto = createAssetInstance(mediaMap["Photo_Page_Banner"]);
    bgPhoto.resize(1440, 316);
    bgPhoto.x = 0;
    bgPhoto.y = 0;
    banner.appendChild(bgPhoto);

    const content = figma.createFrame();
    content.name = "Content";
    content.layoutMode = "VERTICAL";
    content.primaryAxisAlignItems = "CENTER";
    content.counterAxisAlignItems = "CENTER";
    content.itemSpacing = 5;
    content.fills = [];

    content.appendChild(createAssetInstance(mediaMap["Logo_Furniro"]));

    const t = figma.createText();
    t.fontName = { family: "Poppins", style: "Medium" };
    t.fontSize = 48;
    t.characters = title;
    t.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
    content.appendChild(t);

    const bcRow = figma.createFrame();
    bcRow.layoutMode = "HORIZONTAL";
    bcRow.itemSpacing = 6;
    bcRow.counterAxisAlignItems = "CENTER";
    bcRow.fills = [];

    breadcrumbs.forEach((bc, idx) => {
      const bcTxt = figma.createText();
      bcTxt.fontName = { family: "Poppins", style: idx === breadcrumbs.length - 1 ? "Light" : "Bold" };
      bcTxt.fontSize = 16;
      bcTxt.characters = bc;
      bcTxt.fills = [{ type: 'SOLID', color: { r: 0, g: 0, b: 0 } }];
      bcRow.appendChild(bcTxt);

      if (idx < breadcrumbs.length - 1) {
        bcRow.appendChild(createAssetInstance(mediaMap["Icon_Chevron_Right"]));
      }
    });
    content.appendChild(bcRow);

    content.x = (1440 - content.width) / 2;
    content.y = (316 - content.height) / 2;
    banner.appendChild(content);
    return banner;
  }

