  function buildProductCard(data, isHover = false) {
    const card = figma.createFrame();
    card.name = `Product Card - ${data.name}${isHover ? " (Hover)" : ""}`;
    card.resize(285, 446);
    card.fills = [{ type: 'SOLID', color: GRAY_LIGHT }];
    card.clipsContent = true;

    const photo = createAssetInstance(mediaMap[data.photo]);
    photo.resize(285, 301);
    photo.x = 0;
    photo.y = 0;
    card.appendChild(photo);

    if (data.badge) {
      const badge = figma.createFrame();
      badge.resize(48, 48);
      badge.cornerRadius = 24;
      badge.fills = [{ type: 'SOLID', color: data.badgeType === 'sale' ? RED_BADGE : GREEN_BADGE }];
      const badgeTxt = figma.createText();
      badgeTxt.fontName = { family: "Poppins", style: "Medium" };
      badgeTxt.fontSize = 16;
      badgeTxt.characters = data.badge;
      badgeTxt.fills = [{ type: 'SOLID', color: WHITE }];
      badge.appendChild(badgeTxt);
      badgeTxt.x = (48 - badgeTxt.width) / 2;
      badgeTxt.y = (48 - badgeTxt.height) / 2;
      badge.x = 221;
      badge.y = 24;
      card.appendChild(badge);
    }

    const info = figma.createFrame();
    info.name = "Info";
    info.resize(285, 145);
    info.x = 0;
    info.y = 301;
    info.fills = [{ type: 'SOLID', color: GRAY_LIGHT }];
    info.layoutMode = "VERTICAL";
    info.paddingLeft = 16;
    info.paddingRight = 16;
    info.paddingTop = 16;
    info.paddingBottom = 20;
    info.itemSpacing = 8;

    const title = figma.createText();
    title.fontName = { family: "Poppins", style: "Bold" };
    title.fontSize = 24;
    title.characters = data.name;
    title.fills = [{ type: 'SOLID', color: DARK }];
    info.appendChild(title);

    const desc = figma.createText();
    desc.fontName = { family: "Poppins", style: "Medium" };
    desc.fontSize = 16;
    desc.characters = data.desc;
    desc.fills = [{ type: 'SOLID', color: GRAY_TEXT }];
    info.appendChild(desc);

    const priceRow = figma.createFrame();
    priceRow.layoutMode = "HORIZONTAL";
    priceRow.itemSpacing = 12;
    priceRow.counterAxisAlignItems = "CENTER";
    priceRow.fills = [];

    const price = figma.createText();
    price.fontName = { family: "Poppins", style: "Bold" };
    price.fontSize = 20;
    price.characters = data.price;
    price.fills = [{ type: 'SOLID', color: DARK }];
    priceRow.appendChild(price);

    if (data.oldPrice) {
      const oldPrice = figma.createText();
      oldPrice.fontName = { family: "Poppins", style: "Regular" };
      oldPrice.fontSize = 16;
      oldPrice.characters = data.oldPrice;
      oldPrice.textDecoration = "STRIKETHROUGH";
      oldPrice.fills = [{ type: 'SOLID', color: { r: 0.7, g: 0.7, b: 0.7 } }];
      priceRow.appendChild(oldPrice);
    }
    info.appendChild(priceRow);
    card.appendChild(info);

    if (isHover) {
      const overlay = figma.createFrame();
      overlay.name = "Hover Overlay";
      overlay.resize(285, 446);
      overlay.x = 0;
      overlay.y = 0;
      overlay.fills = [{ type: 'SOLID', color: { r: 0.2, g: 0.2, b: 0.2 }, opacity: 0.72 }];

      const contentGroup = figma.createFrame();
      contentGroup.layoutMode = "VERTICAL";
      contentGroup.counterAxisAlignItems = "CENTER";
      contentGroup.itemSpacing = 24;
      contentGroup.fills = [];

      const btn = figma.createFrame();
      btn.name = "Add to cart";
      btn.resize(202, 48);
      btn.fills = [{ type: 'SOLID', color: WHITE }];
      const btnTxt = figma.createText();
      btnTxt.fontName = { family: "Poppins", style: "Bold" };
