      btnTxt.characters = "Add to cart";
      btnTxt.fills = [{ type: 'SOLID', color: GOLD }];
      btn.appendChild(btnTxt);
      btnTxt.x = (202 - btnTxt.width) / 2;
      btnTxt.y = (48 - btnTxt.height) / 2;
      contentGroup.appendChild(btn);

      const actRow = figma.createFrame();
      actRow.layoutMode = "HORIZONTAL";
      actRow.itemSpacing = 20;
      actRow.counterAxisAlignItems = "CENTER";
      actRow.fills = [];

      const actions = [
        { icon: "Icon_Share", label: "Share" },
        { icon: "Icon_Compare", label: "Compare" },
        { icon: "Icon_Heart", label: "Like" }
      ];

      actions.forEach(a => {
        const item = figma.createFrame();
        item.name = a.label;
        item.layoutMode = "HORIZONTAL";
        item.itemSpacing = 4;
        item.counterAxisAlignItems = "CENTER";
