      contentGroup.appendChild(actRow);
      contentGroup.x = (285 - contentGroup.width) / 2;
      contentGroup.y = (446 - contentGroup.height) / 2;
      overlay.appendChild(contentGroup);
      card.appendChild(overlay);
    }
    return card;
  }

