(async () => {
  const workspace = figma.root.children.find(p => p.name.includes("03"));
  await figma.setCurrentPageAsync(workspace);

  const home = workspace.children.find(c => c.name === "01_Home");
  const shop = workspace.children.find(c => c.name === "02_Shop");
  const product = workspace.children.find(c => c.name === "03_Product");
  const cartDrawer = workspace.children.find(c => c.name === "04_Cart_Drawer");
  const comparison = workspace.children.find(c => c.name === "05_Comparison");
  const cart = workspace.children.find(c => c.name === "06_Cart");
  const checkout = workspace.children.find(c => c.name === "07_Checkout");
  const contact = workspace.children.find(c => c.name === "08_Contact");
  const blog = workspace.children.find(c => c.name === "09_Blog");

  function addLink(sourceNode, destinationFrame) {
    if (!sourceNode || !destinationFrame) return;
    sourceNode.reactions = [
      {
        action: {
          type: "NODE",
          destinationId: destinationFrame.id,
          navigation: "NAVIGATE",
          transition: null
        },
        trigger: { type: "ON_CLICK" }
      }
    ];
  }

  function findChildByName(parent, name) {
    if (!parent || !("children" in parent)) return null;
    for (const child of parent.children) {
      if (child.name === name || child.name.includes(name)) return child;
      const sub = findChildByName(child, name);
      if (sub) return sub;
    }
    return null;
  }

  // --- 01_Home links ---
  // Shop (nav), BUY NOW, Show More -> 02_Shop
  const homeHeaderNav = findChildByName(home, "Navigation");
  if (homeHeaderNav) {
    const shopNav = homeHeaderNav.children.find(c => c.name === "Shop");
    addLink(shopNav, shop);
    const contactNav = homeHeaderNav.children.find(c => c.name === "Contact");
    addLink(contactNav, contact);
  }
  addLink(findChildByName(home, "BUY NOW"), shop);
  addLink(findChildByName(home, "Show More Button"), shop);

  // any product card -> 03_Product
  const homeProds = findChildByName(home, "Our Products");
  if (homeProds) {
    homeProds.children.forEach(c => {
      if (c.name.includes("Product Card")) addLink(c, product);
    });
  }

  // Compare (hover card) -> 05_Comparison
  const leviosaHover = findChildByName(home, "Product Card - Leviosa (Hover)");
  if (leviosaHover) {
    const compareAct = findChildByName(leviosaHover, "Compare");
    addLink(compareAct, comparison);
  }

  // cart (header) -> 06_Cart
  const homeIcons = findChildByName(home, "Icons");
  if (homeIcons) {
    const cartIcon = homeIcons.children.find(c => c.name.includes("Cart") || c.name.includes("13:26"));
    addLink(cartIcon, cart);
  }

  // Footer Blog link
  const homeFooter = findChildByName(home, "Footer");
  if (homeFooter) {
    const blogLink = findChildByName(homeFooter, "Blog");
    addLink(blogLink, blog);
  }

  // --- 02_Shop links ---
  const shopProds = findChildByName(shop, "Products Grid");
  if (shopProds) {
    shopProds.children.forEach(c => {
      if (c.name.includes("Product Card")) addLink(c, product);
    });
  }
  const shopLeviosaHover = findChildByName(shop, "Product Card - Leviosa (Hover)");
  if (shopLeviosaHover) {
    const compareAct = findChildByName(shopLeviosaHover, "Compare");
    addLink(compareAct, comparison);
  }

  const shopHeaderNav = findChildByName(shop, "Navigation");
  if (shopHeaderNav) {
    const homeNav = shopHeaderNav.children.find(c => c.name === "Home");
    addLink(homeNav, home);
    const contactNav = shopHeaderNav.children.find(c => c.name === "Contact");
    addLink(contactNav, contact);
  }

  const shopIcons = findChildByName(shop, "Icons");
  if (shopIcons) {
    const cartIcon = shopIcons.children.find(c => c.name.includes("Cart"));
    addLink(cartIcon, cart);
  }

